using UnityEngine;

namespace Astrea;

public class ActionInstanceTrailHandler : MonoBehaviour
{
	[Header("VFX")]
	[SerializeField]
	private GameObject diceTrailDraggingPrefab;

	[SerializeField]
	private GameObject diceTrailDraggingMustUsePrefab;

	[Header("Components")]
	[SerializeField]
	private ActionInstanceOutlineHandler actionInstanceOutlineHandler;

	protected DiceTrailDragging diceTrailDragging;

	public void OnGoBackToOriginalPositionAnimation(int layerIndex)
	{
		if (diceTrailDragging != null)
		{
			diceTrailDragging.SetActiveGlow(value: false);
			diceTrailDragging.StopFollowingMouseParticlesEmissionRate();
		}
		else
		{
			SpawnTrail(layerIndex);
			diceTrailDragging.SetActiveGlow(value: false);
			diceTrailDragging.StopFollowingMouseParticlesEmissionRate();
		}
	}

	public void OnDisposeAction()
	{
		if (!(diceTrailDragging == null))
		{
			diceTrailDragging.StopFollowingMouseParticlesEmissionRate();
			diceTrailDragging.SetActiveTrail(value: true);
		}
	}

	public void StoreTrail()
	{
		if (diceTrailDragging != null)
		{
			diceTrailDragging.StoreParticles();
			diceTrailDragging = null;
		}
	}

	public void SpawnTrail(int layerIndex)
	{
		GameObject gameObject = diceTrailDraggingPrefab;
		if (actionInstanceOutlineHandler.MustUse)
		{
			gameObject = diceTrailDraggingMustUsePrefab;
		}
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(gameObject.name, base.transform.position);
		diceTrailDragging = @object.GetComponent<DiceTrailDragging>();
		diceTrailDragging.Initialize(base.transform, layerIndex);
	}

	public void TryDiscardDiceFromTraySetTrailEmissionRate()
	{
		if (diceTrailDragging == null)
		{
			SpawnTrail(6);
			diceTrailDragging.StopFollowingMouseParticlesEmissionRate();
			diceTrailDragging.SetActiveGlow(value: true);
			diceTrailDragging.SetActiveTrail(value: true);
		}
	}

	public void SetActiveGlow(bool toggle)
	{
		diceTrailDragging.SetActiveGlow(toggle);
	}

	public void KillTrail()
	{
		if (!(diceTrailDragging == null))
		{
			diceTrailDragging.SetActiveGlow(value: false);
			diceTrailDragging.SetActiveTrail(value: false);
			StoreTrail();
		}
	}

	public void SetParticlesLayer(int layerIndex)
	{
		diceTrailDragging.SetParticlesLayer(layerIndex);
	}
}
